    function themeValue() { return state.theme === 'system' ? (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light') : state.theme; }
    function applyTheme() { document.documentElement.dataset.theme = themeValue() === 'dark' ? 'dark' : 'light'; const meta = $('meta[name="theme-color"]'); if (meta)
        meta.content = themeValue() === 'dark' ? '#0f1011' : '#f4f4f2'; document.querySelectorAll('[data-action="theme"]').forEach(b => { const icon = $('.theme-icon', b); if (icon)
        icon.textContent = themeValue() === 'dark' ? '☼' : '◐'; b.setAttribute('aria-label', themeValue() === 'dark' ? 'Включить светлую тему' : 'Включить тёмную тему'); }); }
    function toast(message) { let el = $('.toast'); if (!el) {
        el = document.createElement('div');
        el.className = 'toast';
        document.body.append(el);
    } el.textContent = message; el.classList.add('show'); clearTimeout(toast.timer); toast.timer = setTimeout(() => el.classList.remove('show'), 2600); }
    function completedCount() { return modules.filter(m => state.completed[m.id]).length; }
    function overallPercent() { return Math.round(completedCount() / modules.length * 100); }
